#!/bin/sh
# relaunch the stage-5 passes that were running at the 2026-10-29 restart, each from its per-net checkpoint
# (the checkpoint holds the original seed plus every net routed so far; routed nets are skipped).
# run from the repo root:  sh tools/resume_s5.sh
cd "$(dirname "$0")/.." || exit 1

nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2soft.partial.json --rip 3 --soft 0.5 --pops 1500000 --order name --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2soft.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2soft.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2soft.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2short.partial.json --rip 3 --pops 1500000 --order short --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2short.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2short.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r2short.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/plain.partial.json --rip 3 --pops 1500000 --order name --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/plain.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/plain.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/plain.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/soft.partial.json --rip 3 --soft 0.5 --pops 1500000 --order name --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/soft.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/soft.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/soft.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/short.partial.json --rip 3 --pops 1500000 --order short --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/short.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/short.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/swapB/short.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/soft.partial.json --rip 3 --soft 0.5 --pops 1500000 --order name --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/soft.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/soft.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/soft.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/short.partial.json --rip 3 --pops 1500000 --order short --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/short.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/short.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/corner/short.log 2>&1 &
nohup python tools/router.py --model C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/model.json --seed C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r3soft.partial.json --rip 3 --soft 0.5 --pops 1500000 --order name --checkpoint C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r3soft.partial.json --out C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r3soft.json >> C:/Users/tambe/AppData/Local/Temp/routing/s5/swapA/r3soft.log 2>&1 &
